// Rebuild the offline payload from the pinned, SHA-256 checked upstream files.
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { gzipSync } from 'node:zlib';
const provenance = JSON.parse(readFileSync(new URL('../vendor/hermes/provenance.json', import.meta.url), 'utf8'));
const entries = Object.entries(provenance.files).map(([path, facts]) => {
  const relative = path.replace('vendor/', '');
  const bytes = readFileSync(new URL(`../vendor/hermes/${relative}`, import.meta.url));
  if (createHash('sha256').update(bytes).digest('hex') !== facts.sha256) throw Error(`Pinned upstream hash mismatch: ${relative}`);
  return [relative, { sha256: facts.sha256, gzip: gzipSync(bytes, { level: 9 }).toString('base64') }];
});
for (const relative of ['before/LICENSE', 'fixed/LICENSE']) {
  const bytes = readFileSync(new URL(`../vendor/hermes/${relative}`, import.meta.url));
  entries.push([relative, { sha256: createHash('sha256').update(bytes).digest('hex'), gzip: gzipSync(bytes, { level: 9 }).toString('base64') }]);
}
const adapter = readFileSync(new URL('./hermes-adapter.py', import.meta.url), 'utf8');
const output = '// Generated by scripts/build-hermes-bundle.mjs. Upstream source is MIT licensed.\n'
  + '// See vendor/hermes/provenance.json and the embedded LICENSE files.\n'
  + `export const HERMES_FILES = ${JSON.stringify(Object.fromEntries(entries))} as const;\n`
  + `export const HERMES_ADAPTER = ${JSON.stringify(adapter)};\n`;
writeFileSync(new URL('../src/domain/hermes-bundle.ts', import.meta.url), output);
console.log(`Offline pinned-source bundle: ${Buffer.byteLength(output)} bytes.`);
